{
  "compilerOptions": { "target": "ES2020", "useDefineForClassFields": true, "lib": ["ES2020", "DOM", "DOM.Iterable"], "module": "ESNext", "skipLibCheck": true, "moduleResolution": "Bundler", "allowImportingTsExtensions": true, "resolveJsonModule": true, "isolatedModules": true, "noEmit": true, "jsx": "react-jsx", "strict": true, "noUnusedLocals": false, "noUnusedParameters": false },
  "include": ["src"]
}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
export default defineConfig({ plugins: [react()] })

import { useEffect, useMemo, useState } from 'react'
import { Activity, AlertTriangle, Archive, ArrowDownToLine, ArrowLeft, ArrowRight, Award, BatteryCharging, Bell, Building2, Check, ChevronDown, ChevronRight, Clock3, Crosshair, Factory, Flag, FlaskConical, Gauge, Heart, HelpCircle, Home, Inbox, Info, MapPin, Menu, MessageSquare, Minus, Package, Plus, Radio, Radar, Search, Send, Settings, Shield, ShieldCheck, ShoppingBag, Siren, Swords, Target, TrendingUp, Truck, Users, X, Zap } from 'lucide-react'

type Resource = 'cash'|'food'|'oil'|'steel'
type Building = { level:number; readyAt?:number }
type UnitKey = 'infantry'|'vehicles'|'ranged'|'artillery'
type March = { id:number; kind:'Attack'|'Scout'|'Gather'|'Reinforce'; target:string; units:Record<UnitKey,number>; started:number; ends:number; state:'outbound' }
type Game = { resources:Record<Resource,number>; buildings:Record<string,Building>; army:Record<UnitKey,number>; training?:{unit:UnitKey; count:number; ends:number}; research:Record<string,number>; researchJob?:{id:string; ends:number}; marches:March[]; reports:{id:number; title:string; result:string; time:number; detail:string}[]; inventory:{crates:number; speedups:number}; last:number; power:number }

const buildingList = [
  {id:'hq',name:'Command HQ',short:'HQ',icon:'⌂',category:'Command',desc:'The heart of your command. Unlocks new facilities.',base:{cash:220,steel:110},prod:'Command capacity',req:1},
  {id:'farm',name:'Hydroponics Farm',short:'FARM',icon:'♧',category:'Economy',desc:'Feeds your growing expeditionary force.',base:{cash:90,steel:35},prod:'Food +42 /h',req:1,rate:{food:42}},
  {id:'oil',name:'Oil Refinery',short:'OIL',icon:'◉',category:'Economy',desc:'Refines fuel for vehicles and field operations.',base:{cash:125,steel:55},prod:'Oil +26 /h',req:1,rate:{oil:26}},
  {id:'iron',name:'Iron Works',short:'IRON',icon:'⌁',category:'Economy',desc:'Processes raw ore into construction materials.',base:{cash:140,steel:65},prod:'Steel +18 /h',req:1,rate:{steel:18}},
  {id:'steel',name:'Steel Mill',short:'MILL',icon:'▤',category:'Economy',desc:'Advanced alloy production for heavy units.',base:{cash:350,steel:150},prod:'Steel +36 /h',req:3,rate:{steel:36}},
  {id:'concrete',name:'Concrete Plant',short:'MIX',icon:'▦',category:'Economy',desc:'Produces high-grade building composites.',base:{cash:310,steel:125},prod:'Cash +28 /h',req:2,rate:{cash:28}},
  {id:'power',name:'Power Plant',short:'GRID',icon:'ϟ',category:'Infrastructure',desc:'Balances the base energy grid.',base:{cash:240,steel:100},prod:'Grid +24 /h',req:2},
  {id:'warehouse',name:'Supply Depot',short:'DEPOT',icon:'▣',category:'Infrastructure',desc:'Increases the amount of resources you can store.',base:{cash:180,steel:75},prod:'Storage +8,000',req:1},
  {id:'training',name:'Training Center',short:'TRAIN',icon:'✣',category:'Military',desc:'Drills elite infantry and ranged specialists.',base:{cash:260,steel:105},prod:'Infantry • Ranged',req:1},
  {id:'vehicle',name:'Motor Pool',short:'MOTOR',icon:'▰',category:'Military',desc:'Builds and services armored vehicles.',base:{cash:380,steel:170,oil:80},prod:'Vehicle units',req:2},
  {id:'artillery',name:'Fire Support',short:'FIRE',icon:'◎',category:'Military',desc:'Long-range artillery battery and crew school.',base:{cash:520,steel:240,oil:100},prod:'Artillery units',req:3},
  {id:'hospital',name:'Field Hospital',short:'MED',icon:'✚',category:'Military',desc:'Returns wounded personnel to active duty.',base:{cash:320,steel:145},prod:'Wounded recovery',req:2},
  {id:'research',name:'Research Lab',short:'LAB',icon:'⌬',category:'Command',desc:'Develops doctrine and next-generation equipment.',base:{cash:400,steel:175},prod:'Technology',req:2},
  {id:'alliance',name:'Alliance Center',short:'ALLY',icon:'⚑',category:'Command',desc:'Coordinate operations with allied commanders.',base:{cash:300,steel:130},prod:'Alliance operations',req:2},
  {id:'intel',name:'Intelligence Center',short:'INTEL',icon:'◈',category:'Command',desc:'Tracks regional activity and enemy movements.',base:{cash:340,steel:150},prod:'Recon range',req:2},
  {id:'comms',name:'Signal Array',short:'COMMS',icon:'⌁',category:'Infrastructure',desc:'Extends secure communications across the region.',base:{cash:260,steel:100},prod:'March speed +',req:2},
]
const unitData:Record<UnitKey,{name:string;icon:string;cost:Record<Resource,number>;stats:{atk:number;def:number;hp:number;spd:number;power:number;upkeep:number;load:number;time:number};counter:string;line:string;req:string}> = {
 infantry:{name:'Rifle Squad',icon:'♟',cost:{cash:18,food:12,oil:0,steel:3},stats:{atk:12,def:13,hp:85,spd:5,power:4,upkeep:1,load:2,time:5},counter:'Counters artillery',line:'Front',req:'Training Center'},
 vehicles:{name:'Armored Vehicle',icon:'▰',cost:{cash:42,food:7,oil:20,steel:15},stats:{atk:25,def:22,hp:180,spd:8,power:10,upkeep:3,load:8,time:11},counter:'Counters infantry',line:'Front',req:'Motor Pool'},
 ranged:{name:'Marksman Team',icon:'⌖',cost:{cash:28,food:10,oil:2,steel:7},stats:{atk:22,def:7,hp:60,spd:4,power:7,upkeep:2,load:3,time:8},counter:'Counters vehicles',line:'Middle',req:'Training Center'},
 artillery:{name:'Field Artillery',icon:'◎',cost:{cash:55,food:12,oil:24,steel:22},stats:{atk:36,def:5,hp:75,spd:2,power:13,upkeep:4,load:10,time:15},counter:'Counters ranged',line:'Back',req:'Fire Support'},
}
const tiers = [1,2,3,4,5]
const researchData = [
 {id:'logistics',name:'Field Logistics',branch:'Economy',icon:'⌑',desc:'Improve resource efficiency and supply capacity.',bonus:'+8% resource production',cost:120,time:35},
 {id:'ballistics',name:'Advanced Ballistics',branch:'Combat',icon:'⊹',desc:'Upgrade targeting and kinetic impact systems.',bonus:'+10% attack',cost:180,time:55},
 {id:'armor',name:'Reactive Armor',branch:'Combat',icon:'▣',desc:'Reinforced composite plating for all lines.',bonus:'+10% defense & health',cost:180,time:55},
 {id:'drill',name:'Rapid Deployment',branch:'Military',icon:'➤',desc:'Streamline deployment procedures and field drills.',bonus:'+12% march speed',cost:150,time:45},
 {id:'medicine',name:'Combat Medicine',branch:'Military',icon:'✚',desc:'Advanced triage restores more wounded troops.',bonus:'+20% hospital recovery',cost:200,time:60},
 {id:'inteltech',name:'Signal Intercept',branch:'Command',icon:'⌁',desc:'Gather better intelligence before engaging.',bonus:'Improved scouting',cost:160,time:45},
]
const initial:Game = {resources:{cash:1350,food:1250,oil:780,steel:920},buildings:Object.fromEntries(buildingList.map(b=>[b.id,{level:b.id==='hq'?2:b.id==='farm'||b.id==='training'||b.id==='oil'||b.id==='iron'||b.id==='warehouse'||b.id==='power'?1:0}])),army:{infantry:68,vehicles:24,ranged:35,artillery:12},research:{},marches:[],reports:[],inventory:{crates:3,speedups:2},last:Date.now(),power:13640}
const nav = [{id:'base',label:'Command',icon:Home},{id:'army',label:'Army & Training',icon:Shield},{id:'research',label:'Research',icon:FlaskConical},{id:'region',label:'Region Ops',icon:Radar},{id:'inventory',label:'Inventory',icon:Archive},{id:'alliance',label:'Alliance',icon:Users},{id:'mail',label:'Messages',icon:Inbox}]
const fmt=(n:number)=>Math.floor(n).toLocaleString('en-US')
const costFor=(b:typeof buildingList[number],level:number)=>Object.fromEntries(Object.entries(b.base).map(([k,v])=>[k,Math.floor(v*Math.pow(1.62,level))])) as Partial<Record<Resource,number>>
const cap=(g:Game)=>8000+(g.buildings.warehouse.level||0)*8000
const totalArmy=(a:Record<UnitKey,number>)=>Object.values(a).reduce((x,y)=>x+y,0)
const activeArmy=(g:Game)=>{const a={...g.army};g.marches.forEach(m=>Object.entries(m.units).forEach(([k,v])=>a[k as UnitKey]-=v));return a}
function blankGame():Game{return JSON.parse(JSON.stringify(initial))}
function loadGame():Game {try {const saved=localStorage.getItem('frontline-save'); if(saved){const p=JSON.parse(saved);return {...blankGame(),...p,resources:{...initial.resources,...p.resources},buildings:{...initial.buildings,...p.buildings},army:{...initial.army,...p.army},inventory:{...initial.inventory,...p.inventory}}}}catch{} return blankGame()}
function tickGame(input:Game,now:number):Game {
 let g={...input,resources:{...input.resources},buildings:{...input.buildings},army:{...input.army},research:{...input.research},marches:[...input.marches],reports:[...input.reports],last:now}
 const dt=Math.max(0,Math.min((now-input.last)/1000,3600*24*7));
 const boost=1+(g.research.logistics||0)*.08
 for(const b of buildingList){if(b.rate&&g.buildings[b.id].level){const amount=b.rate[Object.keys(b.rate)[0] as keyof typeof b.rate]*g.buildings[b.id].level*boost*dt/3600;const key=Object.keys(b.rate)[0] as Resource;g.resources[key]=Math.min(cap(g),g.resources[key]+amount)}}
 if(g.training&&g.training.ends<=now){g.army[g.training.unit]+=g.training.count;g.training=undefined}
 if(g.researchJob&&g.researchJob.ends<=now){g.research[g.researchJob.id]=(g.research[g.researchJob.id]||0)+1;g.researchJob=undefined}
 for(const [id,b] of Object.entries(g.buildings)){if(b.readyAt&&b.readyAt<=now){g.buildings[id]={level:b.level+1}}}
 g.marches=g.marches.filter(m=>{if(m.ends>now)return true; if(m.kind==='Attack'){
   const our=powerOf(m.units,g);const target=enemyData.find(t=>t.name===m.target)||enemyData[0];const roll=our/(our+target.power);const win=roll>=.48;const loss=Math.max(.08,Math.min(.62,win?.12+(1-roll)*.38:.28+(1-roll)*.26));let wounded=0,lost=0;for(const k of Object.keys(m.units) as UnitKey[]){const cas=Math.floor(m.units[k]*loss);lost+=Math.floor(cas*.55);wounded+=cas-Math.floor(cas*.55);g.army[k]=Math.max(0,g.army[k]-Math.floor(cas*.55))}const reward=win?target.reward:Math.floor(target.reward*.25);g.resources.cash=Math.min(cap(g),g.resources.cash+reward);g.reports.unshift({id:Date.now()+m.id,title:`${win?'Victory':'Defeat'} at ${target.name}`,result:win?'VICTORY':'DEFEAT',time:now,detail:`Force power ${fmt(our)} engaged ${fmt(target.power)} enemy power. ${fmt(lost)} KIA • ${fmt(wounded)} wounded • ${fmt(totalArmy(m.units)-lost-wounded)} survived. ${win?`Secured ${fmt(reward)} cash in recovered equipment.`:'Your forces withdrew under pressure.'}`})
  } else if(m.kind==='Gather'){const loot=Math.floor((m.units.infantry*2+m.units.vehicles*8+m.units.ranged*3+m.units.artillery*10)*(.7+Math.random()*.6));g.resources.steel=Math.min(cap(g),g.resources.steel+loot);g.reports.unshift({id:Date.now()+m.id,title:`Supply cache secured`,result:'COMPLETE',time:now,detail:`The ${m.target} detail returned with ${fmt(loot)} steel and no reported casualties.`})} else if(m.kind==='Scout'){g.reports.unshift({id:Date.now()+m.id,title:`Recon complete: ${m.target}`,result:'INTEL',time:now,detail:`Recon confirms an enemy garrison of ${fmt((enemyData.find(t=>t.name===m.target)||enemyData[0]).power)} power. Approach via the northern corridor.`})} else {g.reports.unshift({id:Date.now()+m.id,title:`Reinforcements delivered`,result:'COMPLETE',time:now,detail:`Your ${fmt(totalArmy(m.units))} reinforcements have joined the allied garrison.`})}return false});g.reports=g.reports.slice(0,12);return g
}
function powerOf(a:Record<UnitKey,number>,g:Game){let out=0;for(const k of tiers){void k}for(const key of Object.keys(a) as UnitKey[]){out+=a[key]*unitData[key].stats.power*(1+(g.research.ballistics||0)*.04)}return out}
const enemyData=[{name:'Raven Outpost',level:3,power:460,reward:380,desc:'Light garrison • Low threat',type:'Outpost'},{name:'Iron Gate Depot',level:5,power:840,reward:720,desc:'Armored patrols • Moderate threat',type:'Supply Depot'},{name:'Black Ridge Relay',level:7,power:1260,reward:1080,desc:'Hardened position • High threat',type:'Signal Relay'},{name:'Dust Devil Cache',level:2,power:320,reward:240,desc:'Unsecured supplies • Low threat',type:'Resource Site'}]

export default function App(){
 const [game,setGame]=useState<Game>(loadGame); const [page,setPage]=useState('base'); const [toast,setToast]=useState(''); const [modal,setModal]=useState<{type:string;target?:string} | null>(null); const [mobileNav,setMobileNav]=useState(false); const [unitTier,setUnitTier]=useState(1); const [unitCount,setUnitCount]=useState(10); const [marchKind,setMarchKind]=useState<'Attack'|'Scout'|'Gather'|'Reinforce'>('Attack'); const [marchTarget,setMarchTarget]=useState(enemyData[0].name); const [marchDraft,setMarchDraft]=useState<Record<UnitKey,number>>({infantry:0,vehicles:0,ranged:0,artillery:0}); const [researchTab,setResearchTab]=useState('All');
 useEffect(()=>{const timer=window.setInterval(()=>setGame(g=>tickGame(g,Date.now())),1000);return()=>window.clearInterval(timer)},[])
 useEffect(()=>{localStorage.setItem('frontline-save',JSON.stringify(game))},[game])
 const active=useMemo(()=>activeArmy(game),[game]); const power=useMemo(()=>powerOf(game.army,game),[game]);
 const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),2800)}
 const update=(fn:(g:Game)=>Game)=>setGame(g=>fn(g));
 const spend=(cost:Partial<Record<Resource,number>>,g:Game)=>Object.entries(cost).every(([k,v])=>g.resources[k as Resource]>=Number(v));
 const pay=(g:Game,cost:Partial<Record<Resource,number>>)=>{for(const [k,v] of Object.entries(cost))g.resources[k as Resource]-=Number(v)}
 const build=(id:string)=>{update(old=>{const g={...old,resources:{...old.resources},buildings:{...old.buildings}};const data=buildingList.find(b=>b.id===id)!;const b=g.buildings[id];if(!b||b.readyAt||b.level>=5){notify('Facility is already upgrading or at maximum level.');return old}if(data.req>(g.buildings.hq.level||1)){notify(`Requires Command HQ level ${data.req}.`);return old}const cost=costFor(data,b.level);if(!spend(cost,g)){notify('Insufficient resources for this upgrade.');return old}pay(g,cost);g.buildings[id]={...b,readyAt:Date.now()+(8+b.level*11)*1000};return g});notify('Construction order confirmed.')}
 const instantBuild=()=>{update(old=>{const g=tickGame(old,Date.now()+3600000);g.inventory.speedups=Math.max(0,g.inventory.speedups-1);return g});setModal(null);notify('Speedup applied to active operation.')}
 const startTraining=()=>{const key=modal?.target as UnitKey;const count=Math.max(1,Math.floor(unitCount));const activeReq=key==='vehicles'?'vehicle':key==='artillery'?'artillery':'training';if(!game.buildings[activeReq]?.level){notify(`Build the ${unitData[key].req} first.`);return}if(game.training){notify('Training queue is busy.');return}const multiplier=1+(unitTier-1)*.52;const cost=Object.fromEntries(Object.entries(unitData[key].cost).map(([k,v])=>[k,Math.ceil(v*count*multiplier)])) as Record<Resource,number>;if(!spend(cost,game)){notify('Insufficient resources to train this force.');return}update(old=>{const g={...old,resources:{...old.resources}};pay(g,cost);g.training={unit:key,count,ends:Date.now()+Math.ceil(unitData[key].stats.time*count/12)*1000};return g});setModal(null);notify(`${count} ${unitData[key].name} queued for training.`)}
 const startResearch=(id:string)=>{const d=researchData.find(r=>r.id===id)!;if(game.researchJob){notify('Research Lab queue is busy.');return}if((game.research[id]||0)>=1){notify('This technology is already researched.');return}if(!game.buildings.research.level){notify('Build a Research Lab to unlock technologies.');return}if(game.resources.cash<d.cost||game.resources.steel<Math.floor(d.cost*.5)){notify('Insufficient resources for this research.');return}update(old=>{const g={...old,resources:{...old.resources},research:{...old.research}};g.resources.cash-=d.cost;g.resources.steel-=Math.floor(d.cost*.5);g.researchJob={id,ends:Date.now()+d.time*1000};return g});notify(`${d.name} research started.`)}
 const openMarch=(kind:'Attack'|'Scout'|'Gather'|'Reinforce',target:string)=>{setMarchKind(kind);setMarchTarget(target);setMarchDraft({infantry:0,vehicles:0,ranged:0,artillery:0});setModal({type:'march',target})}
 const deploy=()=>{const n=totalArmy(marchDraft);if(!n){notify('Select at least one unit to deploy.');return}for(const k of Object.keys(marchDraft) as UnitKey[]){if(marchDraft[k]>active[k]){notify('Deployment exceeds available troops.');return}}const duration=marchKind==='Gather'?35:marchKind==='Scout'?20:marchKind==='Reinforce'?24:30;update(old=>({...old,marches:[...old.marches,{id:Date.now(),kind:marchKind,target:marchTarget,units:marchDraft,started:Date.now(),ends:Date.now()+duration*1000,state:'outbound'}]}));setModal(null);notify(`${marchKind} march deployed to ${marchTarget}.`)}
 const quickPackage=()=>{if(!game.inventory.crates){notify('No supply crates remaining.');return}update(old=>{const g={...old,inventory:{...old.inventory,crates:old.inventory.crates-1},resources:{...old.resources}};g.resources.cash=Math.min(cap(g),g.resources.cash+500);g.resources.food=Math.min(cap(g),g.resources.food+400);g.resources.oil=Math.min(cap(g),g.resources.oil+250);g.resources.steel=Math.min(cap(g),g.resources.steel+300);return g});notify('Field supply package opened: resources replenished.')}
 const buySpeedup=()=>{if(game.resources.cash<280){notify('You need 280 cash to requisition a speedup.');return}update(old=>({...old,resources:{...old.resources,cash:old.resources.cash-280},inventory:{...old.inventory,speedups:old.inventory.speedups+1}}));notify('One-hour speedup added to inventory.')}
 const energyIn=game.buildings.power.level*24+game.buildings.hq.level*6;const energyOut=Math.max(0,game.buildings.training.level*5+game.buildings.vehicle.level*7+game.buildings.artillery.level*8+game.buildings.research.level*4);const net=energyIn-energyOut;
 const fmtTime=(end:number)=>{const s=Math.max(0,Math.ceil((end-Date.now())/1000));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
 const renderHeader=(title:string,subtitle:string)=><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> OPERATIONAL THEATER <span className="slash">/</span> SECTOR 07</div><h1>{title}</h1><p>{subtitle}</p></div><div className="heading-actions"><button className="icon-btn" onClick={()=>setModal({type:'notifications'})} aria-label="Notifications"><Bell size={17}/><i className="notification-dot"/></button><button className="commander-chip" onClick={()=>setModal({type:'profile'})}><span className="avatar">AK</span><span><b>Alex K.</b><small>Commander · Lvl 08</small></span><ChevronDown size={14}/></button></div></div>
 return <div className="app-shell">
  <aside className={`sidebar ${mobileNav?'open':''}`}><div className="brand"><div className="brand-mark"><Crosshair size={22}/></div><div><b>FRONTLINE</b><span>COMMAND</span></div><button className="mobile-close" onClick={()=>setMobileNav(false)}><X size={18}/></button></div><div className="season-card"><div className="season-top"><span className="season-label">SEASON 04</span><span className="season-live"><i/> LIVE</span></div><strong>OPERATION<br/>IRON VEIL</strong><div className="season-progress"><i style={{width:'61%'}}/></div><small>SECTOR CONTROL <b>61%</b></small></div><div className="nav-caption">COMMAND CENTER</div><nav>{nav.map(item=>{const I=item.icon;return <button key={item.id} className={`nav-item ${page===item.id?'active':''}`} onClick={()=>{setPage(item.id);setMobileNav(false)}}><I size={18}/><span>{item.label}</span>{item.id==='mail'&&<em>2</em>}{page===item.id&&<i className="nav-active"/>}</button>})}</nav><div className="sidebar-bottom"><div className="alliance-mini"><div className="alliance-crest">⚑</div><div><small>YOUR ALLIANCE</small><b>VANGUARD</b><span>18 members online</span></div><ChevronRight size={14}/></div><button className="nav-item" onClick={()=>setModal({type:'settings'})}><Settings size={17}/><span>Settings</span></button><div className="server-status"><span className="status-dot"/> ALL SYSTEMS NOMINAL <span>v1.4.08</span></div></div></aside>
  {mobileNav&&<div className="backdrop" onClick={()=>setMobileNav(false)}/>}
  <main className="main-area"><header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav(true)}><Menu size={19}/></button><div className="breadcrumb"><span>FRONTLINE COMMAND</span><ChevronRight size={13}/><b>{nav.find(n=>n.id===page)?.label||'Command'}</b></div><div className="topbar-right"><div className="network"><span className="status-dot"/> SECURE LINK <b>STABLE</b></div><div className="divider"/><button className="text-icon" onClick={()=>setModal({type:'help'})}><HelpCircle size={16}/> <span>Help</span></button></div></header>
   <div className="content">
    {page==='base'&&<>{renderHeader('Command Center','Your forward operating base is secure. Review your assets and issue orders.')}
    <div className="resource-strip">{([['cash','CASH','◆','#64a9ff'],['food','FOOD','✣','#72d9a1'],['oil','OIL','◉','#f4bd63'],['steel','STEEL','▧','#a9b5c5']] as const).map(([key,label,icon,color])=><div className="resource-cell" key={key}><span className="resource-icon" style={{color}}>{icon}</span><div><small>{label}</small><strong>{fmt(game.resources[key])}<span className="capacity"> / {fmt(cap(game))}</span></strong><em className="positive">+{fmt(buildingList.reduce((sum,b)=>sum+(b.rate&&b.rate[key]?b.rate[key]*game.buildings[b.id].level:0),0))}<small>/h</small></em></div><div className="resource-bar"><i style={{width:`${Math.min(100,game.resources[key]/cap(game)*100)}%`,background:color}}/></div></div>)}<div className="energy-cell"><span className="energy-symbol"><Zap size={17}/></span><div><small>ENERGY GRID</small><strong className={net>=0?'energy-positive':'energy-negative'}>{net>=0?'+':''}{net} <span>NET / H</span></strong><em>Production vs. consumption</em></div><button onClick={()=>setModal({type:'energy'})}><Info size={14}/></button></div></div>
    <section className="hero-panel"><div className="hero-copy"><div className="hero-tag"><span className="live-dot"/> BASE STATUS <span>•</span> SECURE</div><h2>Mission ready,<br/><span>Commander.</span></h2><p>Build your capabilities. The theater is shifting—your next decision matters.</p><div className="hero-stats"><div><span>BASE POWER</span><b><Zap size={14}/>{fmt(power)}</b></div><div><span>ACTIVE TROOPS</span><b><Users size={14}/>{fmt(totalArmy(game.army))}</b></div><div><span>DEPLOYED</span><b><Send size={14}/>{fmt(totalArmy(game.army)-totalArmy(active))}</b></div></div></div><div className="hero-art"><div className="radar-ring ring-one"/><div className="radar-ring ring-two"/><div className="radar-ring ring-three"/><div className="radar-cross horizontal"/><div className="radar-cross vertical"/><div className="radar-sweep"/><div className="radar-center"><Crosshair size={30}/></div><span className="radar-label label-n">N 07° 42′</span><span className="radar-label label-e">SECTOR 07</span><span className="radar-label label-s">SIGNAL SECURE</span><i className="blip blip-a"/><i className="blip blip-b"/><i className="blip blip-c"/></div><div className="hero-coordinate">38° 53′ 12.4″ N<br/>77° 02′ 06.8″ W</div></section>
    <div className="dashboard-grid"><section className="panel buildings-panel"><div className="panel-header"><div><div className="eyebrow">YOUR INSTALLATION</div><h3>Base Facilities <span className="count-pill">{buildingList.filter(b=>game.buildings[b.id].level).length} / {buildingList.length}</span></h3></div><button className="link-button" onClick={()=>setModal({type:'allbuildings'})}>FACILITY ROSTER <ArrowRight size={14}/></button></div><div className="building-grid">{buildingList.filter(b=>game.buildings[b.id].level||b.req<=game.buildings.hq.level).slice(0,8).map(b=>{const lvl=game.buildings[b.id];return <div className={`building-card ${lvl.readyAt?'upgrading':''}`} key={b.id} onClick={()=>setModal({type:'building',target:b.id})}><div className="building-top"><span className="building-symbol">{b.icon}</span><span className={`building-level ${lvl.level?'':'locked'}`}>{lvl.readyAt?'UPGRADING':lvl.level?`LVL ${lvl.level}`:'NEW'}</span></div><strong>{b.name}</strong><small>{b.prod}</small>{lvl.readyAt?<div className="building-timer"><Clock3 size={12}/>{fmtTime(lvl.readyAt)}</div>:<div className="building-status"><span className={lvl.level?'status-dot':'status-dot muted'}/>{lvl.level?'OPERATIONAL':'AVAILABLE'}<ChevronRight size={13}/></div>}</div>})}</div><button className="facilities-footer" onClick={()=>setModal({type:'allbuildings'})}><Building2 size={14}/> VIEW ALL {buildingList.length} FACILITIES <ArrowRight size={14}/></button></section>
    <aside className="right-rail"><section className="panel quick-panel"><div className="panel-header compact"><div><div className="eyebrow">OPERATIONS</div><h3>Quick Dispatch</h3></div><span className="online-pill"><i/> {game.marches.length} ACTIVE</span></div><button className="dispatch-row" onClick={()=>{setPage('region')}}><span className="dispatch-icon blue"><Target size={17}/></span><span><b>Regional Operations</b><small>Review targets & deploy units</small></span><ChevronRight size={16}/></button><button className="dispatch-row" onClick={()=>setPage('army')}><span className="dispatch-icon green"><Users size={17}/></span><span><b>Train New Units</b><small>{game.training?`${unitData[game.training.unit].name} in training`:'Reinforce your field force'}</small></span><ChevronRight size={16}/></button><button className="dispatch-row" onClick={()=>setPage('research')}><span className="dispatch-icon amber"><FlaskConical size={17}/></span><span><b>Research & Development</b><small>{game.researchJob?'Lab active':'Unlock new capabilities'}</small></span><ChevronRight size={16}/></button></section>
    <section className="panel activity-panel"><div className="panel-header compact"><div><div className="eyebrow">THEATER FEED</div><h3>Latest Activity</h3></div><button className="dots-btn" onClick={()=>setPage('mail')}>•••</button></div>{game.reports.length?game.reports.slice(0,3).map((r,i)=><div className="activity-item" key={r.id}><span className={`activity-mark ${r.result==='VICTORY'?'success':r.result==='DEFEAT'?'danger':''}`}>{r.result==='VICTORY'?<Check size={14}/>:r.result==='DEFEAT'?<AlertTriangle size={14}/>:<Radio size={14}/>}</span><div><b>{r.title}</b><small>{new Date(r.time).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} · {r.result}</small></div></div>):<div className="empty-activity"><span className="empty-icon"><Activity size={18}/></span><b>No recent activity</b><small>Operations will appear here.</small></div>}<button className="activity-footer" onClick={()=>setPage('mail')}>VIEW OPERATION LOG <ArrowRight size={13}/></button></section></aside></div>
    <div className="bottom-grid"><section className="panel roster-panel"><div className="panel-header compact"><div><div className="eyebrow">FORCE READINESS</div><h3>Garrison Overview</h3></div><button className="link-button" onClick={()=>setPage('army')}>MANAGE FORCE <ArrowRight size={14}/></button></div><div className="troop-summary">{(Object.keys(unitData) as UnitKey[]).map(k=><div className="troop-item" key={k}><span className="troop-icon">{unitData[k].icon}</span><div><small>{unitData[k].name}</small><b>{fmt(game.army[k])}</b></div><span className="troop-power">{fmt(game.army[k]*unitData[k].stats.power)} <small>PWR</small></span></div>)}</div></section><section className="panel objective-panel"><div className="objective-flag"><Flag size={17}/></div><div><div className="eyebrow">COMMAND OBJECTIVE · 01</div><b>Secure the perimeter</b><small>Scout a regional target to reveal enemy strength.</small><div className="objective-progress"><span/><small>0 / 1</small></div></div><button onClick={()=>setPage('region')}><ArrowRight size={15}/></button></section></div></>}
    {page==='army'&&<ArmyPage game={game} active={active} onTrain={k=>{setUnitCount(10);setUnitTier(1);setModal({type:'train',target:k})}} onManage={()=>setModal({type:'manage'})} fmtTime={fmtTime} />}
    {page==='research'&&<ResearchPage game={game} tab={researchTab} setTab={setResearchTab} onResearch={startResearch} fmtTime={fmtTime} />}
    {page==='region'&&<RegionPage game={game} onDispatch={openMarch} fmtTime={fmtTime}/ >}
    {page==='inventory'&&<InventoryPage game={game} onPackage={quickPackage} onBuy={buySpeedup} />}
    {page==='alliance'&&<AlliancePage game={game} notify={notify}/>}
    {page==='mail'&&<MailPage game={game} setModal={setModal}/>}
   </div>
  </main>
  {modal&&<div className="modal-backdrop" onClick={()=>setModal(null)}><div className={`modal ${modal.type==='allbuildings'?'wide-modal':''}`} onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setModal(null)}><X size={18}/></button>
   {modal.type==='building'&&<BuildingModal id={modal.target!} game={game} onBuild={build} onSpeedup={instantBuild} onClose={()=>setModal(null)} fmtTime={fmtTime}/>}
   {modal.type==='allbuildings'&&<AllBuildings game={game} onSelect={id=>setModal({type:'building',target:id})}/>}
   {modal.type==='train'&&<div className="modal-content"><div className="modal-icon blue-icon">{unitData[modal.target as UnitKey].icon}</div><div className="eyebrow">PERSONNEL & TRAINING</div><h2>Train {unitData[modal.target as UnitKey].name}</h2><p>Prepare a new unit for your active field force.</p><div className="tier-select"><span>UNIT TIER</span><div>{tiers.map(t=><button key={t} className={unitTier===t?'selected':''} onClick={()=>setUnitTier(t)} disabled={t>(game.buildings.hq.level||1)+1}>T{t}</button>)}</div></div><label className="field-label">UNITS TO TRAIN <span>MAX 250</span></label><div className="number-input"><button onClick={()=>setUnitCount(Math.max(1,unitCount-5))}><Minus size={15}/></button><input type="number" min="1" max="250" value={unitCount} onChange={e=>setUnitCount(Math.min(250,Math.max(1,Number(e.target.value))))}/><button onClick={()=>setUnitCount(Math.min(250,unitCount+5))}><Plus size={15}/></button></div><div className="cost-box"><b>REQUIRED RESOURCES</b>{Object.entries(unitData[modal.target as UnitKey].cost).filter(([,v])=>Number(v)>0).map(([k,v])=><span key={k} className={game.resources[k as Resource]<Number(v)*unitCount*(1+(unitTier-1)*.52)?'insufficient':''}>{k.toUpperCase()} <b>{fmt(Number(v)*unitCount*(1+(unitTier-1)*.52))}</b></span>)}</div><button className="primary-btn full-btn" onClick={startTraining}>QUEUE TRAINING <ArrowRight size={15}/></button></div>}
   {modal.type==='march'&&<div className="modal-content"><div className="modal-icon red-icon"><Crosshair size={23}/></div><div className="eyebrow">FIELD OPERATIONS · DISPATCH</div><h2>Deploy a march</h2><p>Assign a force to {marchTarget}. Committed troops remain in your garrison but are unavailable until they return.</p><div className="mission-tabs">{(['Attack','Scout','Gather','Reinforce'] as const).map(k=><button key={k} className={marchKind===k?'selected':''} onClick={()=>setMarchKind(k)}>{k}</button>)}</div><label className="field-label">DEPLOYMENT COMPOSITION <span>{fmt(totalArmy(active))} AVAILABLE</span></label><div className="deployment-list">{(Object.keys(unitData) as UnitKey[]).map(k=><div className="deploy-line" key={k}><span className="deploy-unit-icon">{unitData[k].icon}</span><span>{unitData[k].name}<small>{unitData[k].line} line · {fmt(active[k])} ready</small></span><div className="deploy-controls"><button onClick={()=>setMarchDraft(d=>({...d,[k]:Math.max(0,d[k]-5)}))}>−</button><input type="number" min="0" max={active[k]} value={marchDraft[k]} onChange={e=>setMarchDraft(d=>({...d,[k]:Math.max(0,Math.min(active[k],Number(e.target.value)))}))}/><button onClick={()=>setMarchDraft(d=>({...d,[k]:active[k]}))}>MAX</button></div></div>)}</div><div className="march-summary"><span>FORCE POWER <b>{fmt(powerOf(marchDraft,game))}</b></span><span>EST. DURATION <b>{marchKind==='Scout'?'00:20':marchKind==='Gather'?'00:35':'00:30'}</b></span></div><button className="primary-btn full-btn" onClick={deploy}><Send size={15}/> CONFIRM DEPLOYMENT</button></div>}
   {modal.type==='profile'&&<ProfileModal game={game}/>}
   {modal.type==='notifications'&&<NotificationModal game={game}/>}
   {modal.type==='energy'&&<div className="modal-content"><div className="modal-icon amber-icon"><Zap size={22}/></div><div className="eyebrow">BASE INFRASTRUCTURE</div><h2>Energy grid</h2><p>Energy is not stored. It represents your base's current production versus facility consumption.</p><div className="energy-detail"><span>Power production <b>+{energyIn} / h</b></span><span>Facility consumption <b>−{energyOut} / h</b></span><span>Net grid output <b className={net>=0?'positive-text':'negative-text'}>{net>=0?'+':''}{net} / h</b></span></div></div>}
   {modal.type==='settings'&&<div className="modal-content"><div className="modal-icon blue-icon"><Settings size={22}/></div><div className="eyebrow">PREFERENCES</div><h2>Command settings</h2><p>Your progress is saved automatically to this device.</p><div className="setting-row"><span>Local save status<small>Autosave enabled</small></span><span className="online-pill"><i/> SAVED</span></div><button className="secondary-btn full-btn" onClick={()=>{localStorage.removeItem('frontline-save');setGame(blankGame());setModal(null);notify('Local command profile reset.')}}>RESET COMMAND PROFILE</button></div>}
   {modal.type==='help'&&<div className="modal-content"><div className="modal-icon blue-icon"><HelpCircle size={22}/></div><div className="eyebrow">FIELD MANUAL</div><h2>Commander's guide</h2><p>Expand your base to produce supplies, train units, and research doctrine. Dispatch troops from Region Ops to scout, gather or engage targets. Troops on a march remain part of your total force but cannot be redeployed until they return.</p><div className="guide-tip"><Info size={16}/> Combat outcome is deterministic: relative force power, unit roles, research and enemy strength determine the result.</div></div>}
   {modal.type==='manage'&&<div className="modal-content"><div className="modal-icon blue-icon"><Shield size={22}/></div><div className="eyebrow">GARRISON MANAGEMENT</div><h2>Force availability</h2><p>Committed troops remain part of your total army, but are temporarily unavailable for new deployments.</p>{(Object.keys(unitData) as UnitKey[]).map(k=><div className="setting-row" key={k}><span>{unitData[k].name}<small>{unitData[k].line} line</small></span><b>{fmt(active[k])} <small>/ {fmt(game.army[k])} AVAILABLE</small></b></div>)}</div>}
   {modal.type==='notifications'&&<NotificationModal game={game}/>}
   {modal.type==='profile'&&null}
  </div></div>}
  {toast&&<div className="toast"><span className="toast-check"><Check size={14}/></span>{toast}</div>}
 </div>
}

