function ArmyPage({game,active,onTrain,onManage,fmtTime}:{game:Game;active:Record<UnitKey,number>;onTrain:(k:UnitKey)=>void;onManage:()=>void;fmtTime:(n:number)=>string}){
 const total=totalArmy(game.army);return <>{<div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> PERSONNEL & READINESS</div><h1>Army & Training</h1><p>Train, equip and deploy your expeditionary force.</p></div><div className="heading-actions"><button className="secondary-btn" onClick={onManage}><Users size={15}/> FORCE AVAILABILITY</button></div></div>}
 <section className="army-overview"><div><span className="eyebrow">TOTAL FIELD STRENGTH</span><strong>{fmt(total)}</strong><small>PERSONNEL ACROSS ALL DEPLOYMENTS</small></div><div><span className="eyebrow">AVAILABLE FORCES</span><strong>{fmt(totalArmy(active))}</strong><small>READY FOR TASKING</small></div><div><span className="eyebrow">ARMY POWER</span><strong>{fmt(powerOf(game.army,game))}</strong><small>COMBAT RATING</small></div><div><span className="eyebrow">MORALE</span><strong className="morale-score">92<span>%</span></strong><small>HIGH · +3 THIS WEEK</small></div></section>
 <section className="panel page-panel"><div className="panel-header"><div><div className="eyebrow">UNIT ROSTER</div><h3>Expeditionary Force <span className="count-pill">4 BRANCHES</span></h3></div><div className="line-legend"><span><i className="line-dot front"/>FRONT</span><span><i className="line-dot middle"/>MIDDLE</span><span><i className="line-dot back"/>BACK</span></div></div><div className="unit-roster">{(Object.keys(unitData) as UnitKey[]).map(k=>{const u=unitData[k];const locked=(k==='vehicles'&&!game.buildings.vehicle.level)||(k==='artillery'&&!game.buildings.artillery.level);return <div className={`unit-card ${locked?'locked-card':''}`} key={k}><div className="unit-card-top"><span className="unit-portrait">{u.icon}</span><span className={`line-label ${u.line.toLowerCase()}`}>{u.line} line</span></div><h4>{u.name}</h4><small className="unit-subtitle">{u.req} · Tier {Math.min(5,(game.buildings.hq.level||1)+1)} unlocked</small><div className="unit-strength"><b>{fmt(game.army[k])}</b><span>IN GARRISON</span><em className={active[k]===game.army[k]?'':'deployed-text'}>{fmt(active[k])} available</em></div><div className="unit-stats"><span><b>{u.stats.atk}</b> ATK</span><span><b>{u.stats.def}</b> DEF</span><span><b>{u.stats.hp}</b> HP</span><span><b>{u.stats.spd}</b> SPD</span></div><div className="counter-note"><Target size={13}/>{u.counter}</div><button className="primary-btn full-btn" disabled={locked||!!game.training} onClick={()=>onTrain(k)}>{locked?'FACILITY REQUIRED':game.training?'QUEUE BUSY':'TRAIN UNITS'} <ArrowRight size={14}/></button></div>})}</div></section>
 <div className="army-lower"><section className="panel queue-panel"><div className="panel-header compact"><div><div className="eyebrow">TRAINING QUEUE</div><h3>Current Order</h3></div><span className={`queue-status ${game.training?'busy':'idle'}`}>{game.training?'IN PROGRESS':'IDLE'}</span></div>{game.training?<div className="queue-content"><div className="queue-unit-icon">{unitData[game.training.unit].icon}</div><div className="queue-detail"><b>{game.training.count} {unitData[game.training.unit].name}</b><small>Training Center · Standard issue</small><div className="progress-track"><i style={{width:`${Math.max(3,100-(game.training.ends-Date.now())/Math.max(1000,game.training.ends-game.last)*100)}%`}}/></div></div><b className="queue-time"><Clock3 size={13}/>{fmtTime(game.training.ends)}</b></div>:<div className="empty-queue"><span><Clock3 size={17}/></span><div><b>No active training order</b><small>Start training from any unit roster card.</small></div></div>}</section><section className="panel doctrine-panel"><div className="panel-header compact"><div><div className="eyebrow">DEPLOYMENT DOCTRINE</div><h3>Three-line formation</h3></div><ShieldCheck size={18}/></div><p>Infantry and armored units hold the <b>Front</b>; ranged specialists fire from the <b>Middle</b>; artillery supports from the <b>Back</b>.</p><div className="formation"><span className="front">FRONT<br/><small>Infantry · Armor</small></span><ArrowRight size={14}/><span className="middle">MIDDLE<br/><small>Ranged</small></span><ArrowRight size={14}/><span className="back">BACK<br/><small>Artillery</small></span></div></section></div></>}

function ResearchPage({game,tab,setTab,onResearch,fmtTime}:{game:Game;tab:string;setTab:(s:string)=>void;onResearch:(id:string)=>void;fmtTime:(n:number)=>string}){const cats=['All','Economy','Combat','Military','Command'];return <><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> DOCTRINE & DEVELOPMENT</div><h1>Research & Development</h1><p>Invest in technology to improve production, combat and operational reach.</p></div><div className="heading-actions"><div className="lab-status"><FlaskConical size={16}/><span>RESEARCH LAB <b>{game.buildings.research.level?`LVL ${game.buildings.research.level}`:'OFFLINE'}</b></span></div></div></div>
 <div className="research-hero"><div className="research-orbit"><div/><span><FlaskConical size={25}/></span></div><div><div className="eyebrow">STRATEGIC DEVELOPMENT</div><h2>Knowledge is a force multiplier.</h2><p>Research is permanent and improves every unit in your command.</p><div className="research-meta"><span><b>{Object.keys(game.research).length} / {researchData.length}</b> TECHNOLOGIES</span><span><b>{game.researchJob?'1':'0'}</b> ACTIVE PROJECTS</span></div></div><div className="research-job">{game.researchJob?<><span className="queue-status busy">IN PROGRESS</span><b>{researchData.find(r=>r.id===game.researchJob?.id)?.name}</b><small>Completion in {fmtTime(game.researchJob.ends)}</small><div className="progress-track"><i/></div></>:<><span className="queue-status idle">LAB STANDING BY</span><b>Awaiting research order</b><small>Each technology can be researched once.</small></>}</div></div>
 <div className="filter-tabs">{cats.map(c=><button key={c} className={tab===c?'active':''} onClick={()=>setTab(c)}>{c}</button>)}</div><div className="research-grid">{researchData.filter(r=>tab==='All'||r.branch===tab).map((r,i)=>{const done=!!game.research[r.id];const locked=!game.buildings.research.level;return <article className={`research-card ${done?'researched':''}`} key={r.id}><div className="research-card-head"><span className="research-icon">{r.icon}</span><span className={`branch-tag ${r.branch.toLowerCase()}`}>{r.branch}</span></div><h3>{r.name}</h3><p>{r.desc}</p><div className="research-bonus"><TrendingUp size={14}/>{r.bonus}</div><div className="research-card-footer"><span><Clock3 size={13}/>{r.time} SEC <i/> ◈ {r.cost} CASH</span><button className={done?'done-btn':'small-action'} disabled={done||locked||!!game.researchJob} onClick={()=>onResearch(r.id)}>{done?<><Check size={13}/> COMPLETE</>:locked?'LAB REQUIRED':'RESEARCH'}</button></div></article>})}</div></>}

function RegionPage({game,onDispatch,fmtTime}:{game:Game;onDispatch:(kind:'Attack'|'Scout'|'Gather'|'Reinforce',target:string)=>void;fmtTime:(n:number)=>string}){return <><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> OPERATIONAL THEATER · SECTOR 07</div><h1>Regional Operations</h1><p>Review intelligence cards, identify objectives and dispatch your forces.</p></div><div className="heading-actions"><span className="intel-pill"><Radar size={15}/> INTELLIGENCE UPDATED 2M AGO</span></div></div>
 <div className="region-banner"><div className="region-glyph"><Radar size={27}/><i/><i/><i/></div><div><span className="eyebrow">NORTHERN FRONT · ACTIVE THEATER</span><h2>Central Highlands</h2><p>4 known points of interest · Secure communications</p></div><div className="region-banner-stat"><b>07</b><small>SECTOR</small></div><div className="region-banner-stat"><b>{game.marches.length}</b><small>ACTIVE MARCHES</small></div></div>
 <div className="region-section-head"><div><div className="eyebrow">POINTS OF INTEREST</div><h3>Known targets <span className="count-pill">4 INTEL CARDS</span></h3></div><div className="threat-legend"><span><i className="low"/>LOW</span><span><i className="med"/>MODERATE</span><span><i className="high"/>HIGH</span></div></div><div className="target-grid">{enemyData.map((t,i)=><article className="target-card" key={t.name}><div className={`target-card-image terrain-${i}`}><div className="target-image-grid"/><span className="target-type"><MapPin size={12}/>{t.type.toUpperCase()}</span><span className={`threat-badge ${t.level>=7?'high':t.level>=5?'medium':'low'}`}><i/>{t.level>=7?'HIGH THREAT':t.level>=5?'MODERATE':'LOW THREAT'}</span><div className="target-silhouette"><Crosshair size={33}/></div><small>SECTOR 0{i+3} · {['NORTH RIDGE','EASTERN PASS','BLACK RIDGE','SOUTH BASIN'][i]}</small></div><div className="target-card-body"><div className="target-name-row"><div><span className="eyebrow">HOSTILE POSITION · LVL {t.level}</span><h3>{t.name}</h3></div><span className="target-level">LV {t.level}</span></div><p>{t.desc}</p><div className="target-metrics"><span><Shield size={14}/><b>{fmt(t.power)}</b><small>EST. POWER</small></span><span><Package size={14}/><b>{fmt(t.reward)}</b><small>CONTRABAND</small></span><span><Clock3 size={14}/><b>{i===3?'35':'30'} SEC</b><small>ROUND TRIP</small></span></div><div className="target-actions"><button className="secondary-btn" onClick={()=>onDispatch('Scout',t.name)}><Search size={14}/> SCOUT</button><button className="primary-btn" onClick={()=>onDispatch(i===3?'Gather':'Attack',t.name)}>{i===3?<><Package size={14}/> GATHER</>:<><Swords size={14}/> ATTACK</>}</button></div></div></article>)}</div>
 <section className="panel active-marches"><div className="panel-header compact"><div><div className="eyebrow">FIELD TRACKER</div><h3>Active marches</h3></div><span className="online-pill"><i/>{game.marches.length} IN FIELD</span></div>{game.marches.length?game.marches.map(m=><div className="march-row" key={m.id}><span className={`march-kind-icon ${m.kind.toLowerCase()}`}>{m.kind==='Attack'?<Swords size={16}/>:m.kind==='Scout'?<Search size={16/>:m.kind==='Gather'?<Package size={16}/>:<Users size={16}/>}</span><div className="march-row-main"><b>{m.kind} · {m.target}</b><small>{fmt(totalArmy(m.units))} troops committed · returning automatically</small><div className="progress-track"><i style={{width:`${Math.min(95,((Date.now()-m.started)/(m.ends-m.started))*100)}%`}}/></div></div><span className="march-timer"><Clock3 size={13}/>{fmtTime(m.ends)}</span></div>):<div className="empty-queue"><span><Send size={17}/></span><div><b>No forces deployed</b><small>Choose a regional objective above to begin an operation.</small></div></div>}</section></>}

function InventoryPage({game,onPackage,onBuy}:{game:Game;onPackage:()=>void;onBuy:()=>void}){return <><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> QUARTERMASTER</div><h1>Inventory</h1><p>Manage field supplies, resource caches and operational speedups.</p></div><div className="heading-actions"><span className="intel-pill"><Archive size={15}/> {game.inventory.crates+game.inventory.speedups} ITEMS</span></div></div><section className="panel inventory-section"><div className="panel-header"><div><div className="eyebrow">SUPPLY CRATES</div><h3>Resource Packages <span className="count-pill">{game.inventory.crates} AVAILABLE</span></h3></div><Package size={19}/></div><div className="inventory-grid"><div className="item-card package-card"><div className="item-art package-art"><Package size={36}/><span>FIELD<br/>SUPPLY</span></div><div className="item-content"><div className="item-label">COMMON · RESOURCE</div><h3>Field Supply Package</h3><p>Emergency replenishment containing cash, rations, fuel and construction steel.</p><div className="item-rewards"><span>◆ 500</span><span>✣ 400</span><span>◉ 250</span><span>▧ 300</span></div><button className="primary-btn full-btn" disabled={!game.inventory.crates} onClick={onPackage}><Package size={14}/>{game.inventory.crates?'OPEN PACKAGE':'OUT OF STOCK'}</button></div></div></div></section><section className="panel inventory-section speedup-section"><div className="panel-header"><div><div className="eyebrow">OPERATIONAL TEMPO</div><h3>Speedups & Consumables</h3></div><Clock3 size={19}/></div><div className="inventory-grid"><div className="item-card"><div className="item-art speed-art"><Clock3 size={34}/><span>1H</span></div><div className="item-content"><div className="item-label">RARE · INSTANT</div><h3>One-hour Speedup</h3><p>Complete active construction or research immediately. Your time is mission-critical.</p><div className="item-owned">OWNED <b>{game.inventory.speedups}</b></div><button className="secondary-btn full-btn" disabled={!game.inventory.speedups||(!game.training&&!game.researchJob&&!Object.values(game.buildings).some(b=>b.readyAt))} onClick={()=>{if(game.inventory.speedups){if(game.training||game.researchJob||Object.values(game.buildings).some(b=>b.readyAt)){const updated={...game,inventory:{...game.inventory,speedups:game.inventory.speedups-1}};if(updated.training)updated.army[updated.training.unit]+=updated.training.count;updated.training=undefined;if(updated.researchJob){updated.research[updated.researchJob.id]=(updated.research[updated.researchJob.id]||0)+1;updated.researchJob=undefined}Object.entries(updated.buildings).forEach(([id,b])=>{if(b.readyAt)updated.buildings[id]={level:b.level+1}});localStorage.setItem('frontline-save',JSON.stringify(updated));window.location.reload()}}}}>USE SPEEDUP</button><button className="text-action" onClick={onBuy}><ShoppingBag size={13}/> REQUISITION · 280 CASH</button></div></div><div className="inventory-note"><div className="note-icon"><Info size={17}/></div><div><b>Quartermaster's note</b><p>Speedups can instantly finish one active construction, training, or research order. A requisition costs 280 cash.</p></div></div></div></section></>}

function AlliancePage({game,notify}:{game:Game;notify:(s:string)=>void}){const [msg,setMsg]=useState('');const [messages,setMessages]=useState([{name:'Mako',text:'Good work securing the eastern perimeter.',time:'09:42',you:false},{name:'Vanguard Bot',text:'Alliance contribution milestone reached. +5% gathering for 2h.',time:'09:36',you:false},{name:'Rook',text:'Need scouts on Black Ridge before nightfall.',time:'09:21',you:false}]);const send=()=>{if(!msg.trim())return;setMessages(m=>[...m,{name:'Alex K.',text:msg.trim(),time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),you:true}]);setMsg('')};return <><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> ALLIED NETWORK · SECURE CHANNEL</div><h1>Alliance Command</h1><p>Coordinate with allied commanders and support regional operations.</p></div><div className="heading-actions"><span className="online-pill"><i/> 18 MEMBERS ONLINE</span></div></div><div className="alliance-layout"><section className="panel alliance-overview"><div className="alliance-banner"><div className="large-crest">⚑</div><div><div className="eyebrow">ALLIANCE · EST. 2041</div><h2>Vanguard</h2><p>Hold the line. Secure the future.</p></div><div className="alliance-rank"><small>REGIONAL RANK</small><b>#12</b><span>+2 this week</span></div></div><div className="alliance-stats"><div><small>MEMBERS</small><b>42 <span>/ 50</span></b></div><div><small>ALLIANCE POWER</small><b>2.48M</b></div><div><small>DAILY ACTIVITY</small><b>84<span>%</span></b></div><div><small>YOUR CONTRIBUTION</small><b>1,240</b></div></div><div className="alliance-action-row"><button className="primary-btn" onClick={()=>notify('Alliance assistance requested. Members have been notified.')}><Users size={15}/> REQUEST ASSISTANCE</button><button className="secondary-btn" onClick={()=>notify('Resources contributed to alliance operations.')}><Plus size={15}/> CONTRIBUTE</button></div><div className="member-list-head"><div className="eyebrow">COMMAND STAFF</div><button className="link-button" onClick={()=>notify('Member roster is up to date.')}>VIEW ROSTER <ArrowRight size={13}/></button></div>{[{n:'Mako',r:'ALLIANCE LEADER',p:'284K',c:'#62a9ff'},{n:'Rook',r:'OFFICER',p:'192K',c:'#77d5af'},{n:'Nomad',r:'OFFICER',p:'168K',c:'#e0a76e'}].map((x,i)=><div className="member-row" key={x.n}><span className="member-avatar" style={{background:x.c}}>{x.n[0]}</span><div><b>{x.n}</b><small>{x.r}</small></div><span className="member-power">{x.p} PWR</span><span className={`member-online ${i===2?'away':''}`}/></div>)}</section><section className="panel alliance-chat"><div className="panel-header compact"><div><div className="eyebrow">LIVE CHANNEL</div><h3>Alliance Chat</h3></div><span className="online-pill"><i/> CONNECTED</span></div><div className="chat-feed">{messages.map((m,i)=><div className={`chat-message ${m.you?'own':''}`} key={i}><span className="chat-avatar">{m.name[0]}</span><div><div className="chat-author">{m.name}<small>{m.time}</small></div><p>{m.text}</p></div></div>)}</div><div className="chat-compose"><input value={msg} onChange={e=>setMsg(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="Message your alliance..."/><button onClick={send}><Send size={15}/></button></div><small className="chat-hint">Secure channel · Keep operational details classified</small></section></div></>}

function MailPage({game,setModal}:{game:Game;setModal:(m:{type:string;target?:string}|null)=>void}){const [selected,setSelected]=useState<number|null>(null);const items=game.reports;return <><div className="page-heading"><div><div className="eyebrow"><span className="live-dot"/> SECURE MESSAGING</div><h1>Messages & Reports</h1><p>Operational summaries, field intelligence and command notifications.</p></div><div className="heading-actions"><button className="primary-btn" onClick={()=>setModal({type:'notifications'})}><Bell size={15}/> NOTIFICATIONS</button></div></div><div className="mail-layout"><section className="panel inbox-list"><div className="inbox-tabs"><button className="active">OPERATION REPORTS <span>{items.length}</span></button><button onClick={()=>setModal({type:'notifications'})}>SYSTEM MAIL <span>2</span></button></div>{items.length?items.map((r,i)=><button className={`mail-row ${selected===i?'selected':''}`} onClick={()=>setSelected(i)} key={r.id}><span className={`mail-icon ${r.result.toLowerCase()}`}>{r.result==='VICTORY'?<Award size={16}/>:r.result==='DEFEAT'?<AlertTriangle size={16}/>:<Radio size={16}/>}</span><span className="mail-row-copy"><b>{r.title}</b><small>{r.detail.slice(0,62)}...</small></span><span className="mail-row-time">{new Date(r.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></button>):<div className="empty-inbox"><Inbox size={25}/><b>No battle reports yet</b><small>Completed operations will appear here.</small></div>}</section><section className="panel report-reader">{selected!==null&&items[selected]?<><div className="eyebrow">AFTER-ACTION REPORT · {new Date(items[selected].time).toLocaleString()}</div><h2>{items[selected].title}</h2><span className={`report-result ${items[selected].result.toLowerCase()}`}>{items[selected].result}</span><p>{items[selected].detail}</p><div className="report-field"><b>FIELD SUMMARY</b><span>{items[selected].detail}</span></div><button className="secondary-btn" onClick={()=>setSelected(null)}><ArrowLeft size={14}/> BACK TO INBOX</button></>:<div className="reader-empty"><span><FileReportIcon/></span><b>Select a report</b><small>Your detailed field reports appear here after a march returns.</small></div>}</section></div></>}
function FileReportIcon(){return <Activity size={21}/>}

function BuildingModal({id,game,onBuild,onSpeedup,onClose,fmtTime}:{id:string;game:Game;onBuild:(id:string)=>void;onSpeedup:()=>void;onClose:()=>void;fmtTime:(n:number)=>string}){const b=buildingList.find(x=>x.id===id)!;const state=game.buildings[id];const cost=costFor(b,state.level);const locked=b.req>(game.buildings.hq.level||1);return <div className="modal-content"><div className="facility-modal-art"><span>{b.icon}</span><div className="facility-grid"/></div><div className="eyebrow">{b.category.toUpperCase()} FACILITY · {state.level?'LVL '+state.level:'AVAILABLE'}</div><h2>{b.name}</h2><p>{b.desc}</p><div className="facility-stats"><div><small>CURRENT LEVEL</small><b>{state.level||'—'} <span>/ 5</span></b></div><div><small>UPGRADE TIME</small><b>{8+state.level*11} <span>SEC</span></b></div><div><small>OUTPUT</small><b>{b.prod}</b></div></div>{state.readyAt?<div className="upgrade-active"><span className="queue-status busy">CONSTRUCTION IN PROGRESS</span><b>Completion in {fmtTime(state.readyAt)}</b><button className="secondary-btn full-btn" disabled={!game.inventory.speedups} onClick={onSpeedup}><Clock3 size={14}/> USE SPEEDUP ({game.inventory.speedups})</button></div>:<><div className="cost-box"><b>UPGRADE REQUIREMENTS</b>{Object.entries(cost).map(([k,v])=><span className={game.resources[k as Resource]<Number(v)?'insufficient':''} key={k}>{k.toUpperCase()} <b>{fmt(Number(v))}</b></span>)}{locked&&<span className="requirement-note">Requires Command HQ level {b.req}</span>}</div><button className="primary-btn full-btn" disabled={locked||state.level>=5} onClick={()=>{onBuild(id);onClose()}}>{locked?`REQUIRES HQ LEVEL ${b.req}`:state.level>=5?'MAXIMUM LEVEL':'BEGIN CONSTRUCTION'} <ArrowRight size={14}/></button></>}</div>}
function AllBuildings({game,onSelect}:{game:Game;onSelect:(id:string)=>void}){return <div className="all-buildings-content"><div className="eyebrow">INSTALLATION ROSTER</div><h2>All facilities</h2><p>Expand your base and unlock advanced capabilities through Command HQ progression.</p><div className="all-building-list">{buildingList.map(b=>{const state=game.buildings[b.id];const locked=b.req>(game.buildings.hq.level||1);return <button key={b.id} className="all-building-row" onClick={()=>onSelect(b.id)}><span className="building-symbol">{b.icon}</span><span><b>{b.name}</b><small>{b.category} · {b.prod}</small></span><span className="all-building-level">{state.readyAt?'BUILDING':state.level?`LVL ${state.level}`:locked?`HQ ${b.req} REQUIRED`:'AVAILABLE'}</span><ChevronRight size={15}/></button>})}</div></div>}
function ProfileModal({game}:{game:Game}){return <div className="modal-content profile-modal"><div className="profile-avatar">AK</div><div className="eyebrow">COMMANDER PROFILE · REGION 07</div><h2>Alex K.</h2><p>Vanguard · Member since 2041</p><div className="profile-stats"><span><b>08</b><small>LEVEL</small></span><span><b>{fmt(powerOf(game.army,game))}</b><small>POWER</small></span><span><b>{game.reports.filter(r=>r.result==='VICTORY').length}</b><small>VICTORIES</small></span></div><div className="profile-bio">“Hold the line. Secure the future.”</div></div>}
function NotificationModal({game}:{game:Game}){return <div className="modal-content"><div className="modal-icon blue-icon"><Bell size={21}/></div><div className="eyebrow">COMMAND ALERTS</div><h2>Notifications</h2><p>Recent updates from your base and allied command.</p><div className="notification-list"><div><span className="notice-mark green"><Check size={14}/></span><span><b>Base autosave active</b><small>Your game progress is stored on this device.</small></span><time>NOW</time></div><div><span className="notice-mark blue"><Users size={14}/></span><span><b>Alliance status: Vanguard</b><small>18 allied commanders are currently online.</small></span><time>2M</time></div>{game.reports.slice(0,2).map(r=><div key={r.id}><span className="notice-mark amber"><Radio size={14}/></span><span><b>{r.title}</b><small>{r.result} · field report ready to review.</small></span><time>NEW</time></div>)}</div></div>}

