rtillery*10;g.resources.steel=Math.min(cap(g),g.resources.steel+loot);g.reports.unshift({id:now+m.id,title:'Supply cache secured',result:'COMPLETE',time:now,detail:`The ${m.target} detail returned with ${fmt(loot)} steel and no reported casualties.`})}else g.reports.unshift({id:now+m.id,title:m.kind==='Scout'?`Recon complete: ${m.target}`:'Reinforcements delivered',result:m.kind==='Scout'?'INTEL':'COMPLETE',time:now,detail:m.kind==='Scout'?`Recon confirms an enemy garrison of ${fmt(target.power)} power. Approach via the northern corridor.`:`Your ${fmt(total(m.units))} reinforcements have joined the allied garrison.`});return false});g.reports=g.reports.slice(0,12);return g}

