/* Regional operations */
.region-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(330px,.85fr);gap:14px;align-items:start;margin-bottom:14px}.region-map{height:420px;position:relative;overflow:hidden;border:1px solid #263d51;background:radial-gradient(ellipse at 42% 52%,#23404a 0,#192f3b 28%,#122334 63%,#0d1926 100%)}.map-grid{position:absolute;inset:0;background-image:linear-gradient(#8eb3c00b 1px,transparent 1px),linear-gradient(90deg,#8eb3c00b 1px,transparent 1px);background-size:35px 35px;transform:rotate(-8deg) scale(1.2)}.map-label{position:absolute;color:#718a9d;font:8px 'DM Mono',monospace;letter-spacing:1.2px}.label-north{top:28px;left:40%}.label-west{top:52%;left:18%;transform:rotate(-60deg)}.label-east{right:12%;top:44%}.map-route{position:absolute;height:2px;background:#d3aa5940;transform-origin:left center;box-shadow:0 0 7px #dbb25b3a}.route-one{width:37%;left:28%;top:52%;transform:rotate(-24deg)}.route-two{width:31%;left:39%;top:52%;transform:rotate(25deg)}.map-base,.map-node{position:absolute;z-index:2;display:grid;place-items:center}.map-base{left:43%;top:42%;width:82px;height:68px;background:#163147;border:1px solid #4d94b6;color:#9cdaef;box-shadow:0 0 24px #48b8ef35}.map-base span{font:7px 'DM Mono';letter-spacing:.5px}.map-node{width:43px;height:43px;border:1px solid #745f3a;background:#342b20;color:#edc875;border-radius:50%;transition:.2s}.map-node:hover,.map-node.selected{border-color:#f0c86c;background:#59472a;box-shadow:0 0 20px #ffc95745;transform:scale(1.1)}.map-node small{font:6px 'DM Mono';white-space:nowrap;position:absolute;top:45px;color:#c3b18d}.node-0{left:24%;top:24%}.node-1{right:19%;top:29%}.node-2{right:17%;bottom:18%}.node-3{left:24%;bottom:19%;border-color:#34775d;background:#153b32;color:#80d2aa}.map-compass{position:absolute;right:17px;top:16px;display:grid;justify-items:center;gap:4px;color:#91a7b9;font:9px 'DM Mono'}.map-coords{position:absolute;left:15px;bottom:13px;color:#71889b;font:8px 'DM Mono';letter-spacing:.5px}.region-list{display:grid;gap:9px}.target-card{padding:12px;border:1px solid #203448;background:#101d2b;cursor:pointer;transition:border-color .15s}.target-card:hover,.target-card.target-selected{border-color:#39759b}.target-head{display:flex;align-items:center;gap:9px}.target-symbol{width:32px;height:32px;display:grid;place-items:center;color:#e3b96b;background:#2c281e;border:1px solid #5a4a2d}.target-head>div{flex:1}.target-head .eyebrow{font-size:7px}.target-card h3{margin:3px 0 0;font-size:13px}.threat{font:7px 'DM Mono';letter-spacing:.7px;padding:4px 5px;border:1px solid}.threat-low{color:#7ed4a6;background:#173127;border-color:#28513f}.threat-medium{color:#e5bc69;background:#332b1c;border-color:#62502e}.threat-high{color:#ed8980;background:#351f22;border-color:#633337}.target-card>p{font-size:9px;color:#8da0b2;margin:9px 0}.target-metrics{display:flex;gap:14px;color:#9eafbf;font:8px 'DM Mono'}.target-metrics span{display:flex;align-items:center;gap:4px}.target-actions{display:flex;gap:7px;margin-top:10px}.target-actions .button{flex:1;min-height:30px;font-size:9px}.gather-card{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px;border:1px dashed #31536a;background:#101e2b}.gather-card>div{display:grid;grid-template-columns:30px 1fr;column-gap:8px;align-items:center}.gather-card .resource-icon{grid-row:span 2}.gather-card strong{font-size:10px}.gather-card small{font-size:8px;color:#8296a9}.gather-card .button{font-size:9px;min-height:29px}.count-badge{padding:5px 8px;border:1px solid #2b4358;background:#142536;color:#9fb4c5;font:8px 'DM Mono';white-space:nowrap}.op-row{display:flex;align-items:center;gap:11px;padding:11px 0;border-top:1px solid #203143}.op-row:first-child{border-top:0}.op-icon{width:32px;height:32px;display:grid;place-items:center;color:#82bee4;background:#142a3b;border:1px solid #29455d}.op-main{display:grid;gap:4px;flex:1}.op-main strong{font-size:10px}.op-main span{font-size:8px;color:#8296a8}.op-timer{display:flex;align-items:center;gap:5px;color:#e6c46f;font:9px 'DM Mono'}.icon-button{width:30px;height:30px;border:1px solid #273c50;background:#142333;display:grid;place-items:center}.icon-button:hover{border-color:#4c7593;color:#9bd5f1}
/* Inventory, alliance and dispatches */
.inventory-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-bottom:14px}.inventory-card{display:grid;grid-template-columns:116px 1fr;gap:17px;padding:17px;border:1px solid #22384c;background:linear-gradient(125deg,#142438,#101c2a)}.item-art{min-height:174px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:10px;color:#89ccef;border:1px solid #31516b;background:radial-gradient(circle,#244a63,#13283a 65%);font:8px 'DM Mono';letter-spacing:1px}.inventory-card.speed .item-art{color:#e7bf6b;border-color:#66532d;background:radial-gradient(circle,#504021,#242319 70%)}.item-copy{display:flex;flex-direction:column;align-items:flex-start}.item-copy .eyebrow{font-size:8px}.item-copy h3{font-size:16px;margin:6px 0}.item-copy p{font-size:9px;line-height:1.6;color:#8da0b2;margin:0 0 12px}.item-reward{display:flex;flex-wrap:wrap;gap:7px;margin:auto 0 12px;color:#c5d3df;font:8px 'DM Mono'}.item-reward span{padding:5px 6px;background:#0b1723;border:1px solid #203348}.item-copy .button{font-size:9px;min-height:32px}.inventory-resources{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.inventory-resources>div{display:grid;grid-template-columns:30px 1fr;column-gap:8px;align-items:center;padding:11px;border:1px solid #203447;background:#0b1723}.inventory-resources .resource-icon{grid-row:span 3}.inventory-resources>div>span:nth-child(2){font-size:9px;color:#95a7b8}.inventory-resources strong{font:14px 'DM Mono';color:#e3edf6}.inventory-resources small{font-size:7px;color:#71869a}.alliance-hero{display:flex;align-items:center;gap:15px;padding:18px;margin-bottom:14px;border:1px solid #31526b;background:linear-gradient(110deg,#142c40,#102031)}.alliance-emblem{width:62px;height:62px;display:grid;place-items:center;color:#8ad0e8;background:#18384e;border:1px solid #3c6b85;flex:none}.alliance-hero>div:nth-child(2){flex:1}.alliance-hero h2{font:600 21px Rajdhani;margin:5px 0}.alliance-hero p{font-size:9px;color:#91a4b5;margin:0}.alliance-he